//! The fake network of generated tests (spec 11.5): nothing goes on the
//! network. A connection fails with a generated `NetError`, or reaches a
//! fake server that takes what the case writes and answers once: an HTTP
//! response to an HTTP request, generated bytes to anything else. Which
//! one is decided from the case's seed and the address, so a case meets
//! the same network again when it is shrunk or replayed.

use crate::interp::Interp;
use crate::value::{Eval, Flow, Value};
use std::cell::RefCell;
use std::rc::Rc;

/// What the fake server answers with, besides HTTP's headers.
const BODIES: [&str; 4] = ["", "hello", "{\"ok\": true}", "नमस्ते"];

/// A connection to the fake server.
#[derive(Debug)]
pub(crate) struct Conn {
    address: String,
    seed: u64,
    written: Vec<u8>,
    /// The answer once it is read: `Some` until it has been given.
    answered: Option<bool>,
}

pub(crate) type SharedConn = Rc<RefCell<Conn>>;

fn mix(seed: u64, text: &str) -> u64 {
    text.bytes().fold(seed, |h, b| {
        h.wrapping_mul(0x100_0000_01B3).wrapping_add(u64::from(b))
    })
}

impl Conn {
    /// The answer to what was written so far.
    fn answer(&self) -> Vec<u8> {
        let h = mix(self.seed, &self.address);
        let body = BODIES[(h / 3) as usize % BODIES.len()];
        let request = String::from_utf8_lossy(&self.written);
        let http = ["GET ", "POST ", "PUT ", "DELETE ", "HEAD ", "PATCH "]
            .iter()
            .any(|m| request.starts_with(m));
        if !http {
            return body.as_bytes().to_vec();
        }
        let (status, reason) = [
            (200, "OK"),
            (404, "Not Found"),
            (500, "Internal Server Error"),
        ][(h % 3) as usize];
        format!(
            "HTTP/1.1 {status} {reason}\r\ncontent-type: text/plain\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{body}",
            body.len()
        )
        .into_bytes()
    }
}

impl<'a> Interp<'a> {
    /// `net.connect` and the others in a generated test: an error, or a
    /// connection to the fake server.
    pub(crate) fn fake_net(&mut self, name: &str, address: &str) -> Eval<'a> {
        let seed = self.fake.as_ref().map_or(0, |w| w.borrow().seed());
        let h = mix(seed, address);
        let at = ("address", self.str_value(address));
        let variant = match (name, h % 3) {
            ("connect" | "connect_tls", 2) => {
                let conn = Conn {
                    address: address.to_string(),
                    seed,
                    written: Vec::new(),
                    answered: Some(false),
                };
                return Ok(Value::FakeConn(Rc::new(RefCell::new(conn))));
            }
            (_, 0) => "Refused",
            _ => "TimedOut",
        };
        Err(Flow::Fail(self.builtin_variant(
            "NetError",
            variant,
            vec![at],
        )))
    }

    /// A method of a connection to the fake server.
    pub(crate) fn fake_conn_method(
        &mut self,
        c: &SharedConn,
        name: &str,
        args: &[Value<'a>],
    ) -> Eval<'a> {
        let mut conn = c.borrow_mut();
        Ok(match name {
            "write" => {
                if let Some(Value::Bytes(b)) = args.first() {
                    conn.written.extend_from_slice(b);
                }
                Value::Unit
            }
            "read" => match conn.answered {
                Some(false) => {
                    conn.answered = Some(true);
                    Value::Bytes(conn.answer().into())
                }
                _ => Value::None,
            },
            "close" => {
                conn.answered = None;
                Value::Unit
            }
            "address" => self.str_value(&conn.address),
            "protocol" => Value::None,
            _ => {
                let at = ("address", self.str_value(&conn.address));
                let why = ("reason", self.str_value("not in a generated test"));
                let error = self.builtin_variant("NetError", "Failed", vec![at, why]);
                return Err(Flow::Fail(error));
            }
        })
    }
}
